/**
 * An EXISTS/NOT-EXISTS filter compiled into a {@link MultiJoinPlan} {@link MaskedFilter} may lazily acquire a native
 * semijoin probe (a dataset read stamp). Every engine that consumes such a filter must close it when its run ends; a
 * missed close leaves {@link AdjacencyIntersectionProbe#ACTIVE_PROBES} nonzero and wedges
 * {@code LmdbSailDataset.close()} on its write lock — the query result close then never returns.
 */
public class LmdbNativeExistsFilterProbeCleanupTest {

	private static final String EX = "http://example.com/";
	private static final int PATIENTS = 64;

	@TempDir
	File dataDir;

	private SailRepository repository;

	@BeforeEach
	public void setUp() {
		repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc")));
		try (SailRepositoryConnection conn = repository.getConnection()) {
			ValueFactory vf = conn.getValueFactory();
			IRI patientType = vf.createIRI(EX, "Patient");
			IRI hasEncounter = vf.createIRI(EX, "hasEncounter");
			IRI hasObservation = vf.createIRI(EX, "hasObservation");
			IRI hasCondition = vf.createIRI(EX, "hasCondition");
			IRI value = vf.createIRI(EX, "value");
			// single transaction: direct adjacency stays available, so semijoin probes can actually engage
			conn.begin();
			for (int i = 0; i < PATIENTS; i++) {
				IRI patient = vf.createIRI(EX, "patient" + i);
				conn.add(patient, RDF.TYPE, patientType);
				for (int e = 0; e < 3; e++) {
					IRI encounter = vf.createIRI(EX, "enc" + i + "_" + e);
					conn.add(patient, hasEncounter, encounter);
					IRI observation = vf.createIRI(EX, "obs" + i + "_" + e);
					conn.add(encounter, hasObservation, observation);
					conn.add(observation, value, vf.createLiteral(50 + (i + e) % 30));
					if ((i * 7 + e) % 3 == 0) {
						conn.add(encounter, hasCondition, vf.createIRI(EX, "cond" + i + "_" + e));
					}
				}
			}
			conn.commit();
		}
	}

	@AfterEach
	public void tearDown() {
		if (repository != null) {
			repository.shutDown();
		}
	}

	@Test
	public void notExistsAggregateReleasesEveryNativeProbe() {
		String query = "SELECT (COUNT(DISTINCT ?patient) AS ?c) WHERE {"
				+ " ?patient a <" + EX + "Patient> ."
				+ " ?patient <" + EX + "hasEncounter> ?enc ."
				+ " ?enc <" + EX + "hasObservation> ?obs ."
				+ " ?obs <" + EX + "value> ?value ."
				+ " FILTER(?value IN (50, 60, 70))"
				+ " FILTER NOT EXISTS { ?enc <" + EX + "hasCondition> ?cond } }";
		try (SailRepositoryConnection conn = repository.getConnection()) {
			// several rounds so strategy arbitration explores every engine that can claim the folded filter
			for (int round = 0; round < 8; round++) {
				List<BindingSet> result = assertTimeoutPreemptively(Duration.ofSeconds(30),
						() -> QueryResults.asList(conn.prepareTupleQuery(query).evaluate()),
						"query evaluation or result close wedged on a leaked dataset read stamp");
				assertThat(((Literal) result.get(0).getValue("c")).longValue()).isGreaterThan(0L);
				assertThat(AdjacencyIntersectionProbe.ACTIVE_PROBES.get())
						.as("native semijoin probes still held after result close (round %d)", round)
						.isZero();
			}
		}
	}

	@Test
	public void conjoinedExistsAggregateReleasesEveryNativeProbe() {
		String previousEnabled = System.getProperty("rdf4j.lmdb.janinoCodegen.enabled");
		String previousThreshold = System.getProperty("rdf4j.lmdb.janinoCodegen.thresholdRows");
		String previousSynchronous = System.getProperty("rdf4j.lmdb.janinoCodegen.synchronous");
		String previousWcoj = System.getProperty("rdf4j.lmdb.wcoj.enabled");
		System.setProperty("rdf4j.lmdb.janinoCodegen.enabled", "true");
		System.setProperty("rdf4j.lmdb.janinoCodegen.thresholdRows", "0");
		System.setProperty("rdf4j.lmdb.janinoCodegen.synchronous", "true");
		System.setProperty("rdf4j.lmdb.wcoj.enabled", "false");
		String query = "SELECT (COUNT(*) AS ?c) WHERE {"
				+ " ?patient <" + EX + "hasEncounter> ?enc ."
				+ " FILTER(EXISTS { ?enc <" + EX + "hasCondition> ?condition }"
				+ " && EXISTS { ?patient a <" + EX + "Patient> }) }";
		try (SailRepositoryConnection conn = repository.getConnection()) {
			for (int round = 0; round < 8; round++) {
				List<BindingSet> result = assertTimeoutPreemptively(Duration.ofSeconds(5),
						() -> QueryResults.asList(conn.prepareTupleQuery(query).evaluate()),
						"conjoined EXISTS cleanup wedged on a retained native semijoin probe");
				assertThat(((Literal) result.get(0).getValue("c")).longValue()).isEqualTo(PATIENTS);
				assertThat(AdjacencyIntersectionProbe.ACTIVE_PROBES.get())
						.as("conjoined EXISTS child probes remain retained after aggregate exhaustion (round %d)",
								round)
						.isZero();
			}
			assertThat(QueryResults.asList(conn.prepareTupleQuery("SELECT * WHERE { ?s ?p ?o } LIMIT 1").evaluate()))
					.hasSize(1);
		} finally {
			restoreProperty("rdf4j.lmdb.janinoCodegen.enabled", previousEnabled);
			restoreProperty("rdf4j.lmdb.janinoCodegen.thresholdRows", previousThreshold);
			restoreProperty("rdf4j.lmdb.janinoCodegen.synchronous", previousSynchronous);
			restoreProperty("rdf4j.lmdb.wcoj.enabled", previousWcoj);
		}
	}

	private static void restoreProperty(String name, String value) {
		if (value == null) {
			System.clearProperty(name);
		} else {
			System.setProperty(name, value);
		}
	}
}
